import math

M = 26


def _check_coprime(a):
    if math.gcd(a, M) != 1:
        raise ValueError("a and m must be coprime.")


def encode(plain_text, a, b):
    _check_coprime(a)
    result = []
    for char in plain_text.lower():
        if char.isalpha():
            i = ord(char) - ord("a")
            result.append(chr((a * i + b) % M + ord("a")))
        elif char.isdigit():
            result.append(char)
    return " ".join("".join(result)[i : i + 5] for i in range(0, len(result), 5))


def decode(ciphered_text, a, b):
    _check_coprime(a)
    a_inv = pow(a, -1, M)
    result = []
    for char in ciphered_text:
        if char.isalpha():
            y = ord(char.lower()) - ord("a")
            result.append(chr(a_inv * (y - b) % M + ord("a")))
        elif char.isdigit():
            result.append(char)
    return "".join(result)
